INSERT INTO `news` VALUES (11, 49429095, 'Show HN: Screen memory without screenshots, just text to Markdown', 'Hacker News', 'Dramatize', 42, 15, 'https://github.com/dragthelake/ambient-context', '标题：Show HN: Screen memory without screenshots, just text to Markdown\n来源：Hacker News\n作者：Dramatize\n评分：42\n评论数：15\n\n正文：\nIt\'s a macOS menu bar app that reads the text of your focused window every few seconds through the Accessibility API. No screenshots, no video, or OCR. It writes plain markdown, one file per day, into a folder you choose. Point Claude Code (or anything with file access) at the folder and ask \"what did I work on Tuesday?\" or have it build memory about your projects. The folder contains an AGENTS.md explaining the format to the model. Thought it might be useful for someone so chucked it up on GitHub', '科技情报', '2026-08-25 12:33:24', 'd82d10a85c9429e4d45b70fe3feb90b67c0f2d81c64bd45929e89c9a77ce4964', '2026-08-25 16:51:40');
