INSERT INTO `news` VALUES (30, 49421806, 'Show HN: PicoMQ – Durable Streams over HTTP, on object storage', 'Hacker News', 'adesh_nalpet', 117, 22, 'https://picomq.com/', '标题：Show HN: PicoMQ – Durable Streams over HTTP, on object storage\n来源：Hacker News\n作者：adesh_nalpet\n评分：117\n评论数：22\n\n正文：\nPicoMQ is a Rust server for Durable Streams, built on Object Store. Cheap, URL-addressable, granular streams (create&#x2F;append&#x2F;read&#x2F;long-poll&#x2F;SSE), with Pico Protocol or Durable Streams Protocol as the facade. S3Stream is the stream storage primitive, used in AutoMQ, shipped as a Rust library. Coordination is a command log in Postgres.', '科技情报', '2026-08-25 00:08:17', '9d05475f4e70ffd7937e2dd8afdbd9f3855928aeec53cc611f3177e05d7ea64c', '2026-08-25 16:51:40');
