INSERT INTO `news` VALUES (43, 49389593, 'Show HN: SteppeWM – a stacking IceWM-like Wayland compositor', 'Hacker News', 'uncognic', 16, 5, 'https://github.com/uncognic/steppewm', '标题：Show HN: SteppeWM – a stacking IceWM-like Wayland compositor\n来源：Hacker News\n作者：uncognic\n评分：16\n评论数：5\n\n正文：\nEvery Wayland compositor I could find is a tiling one: sway, river, Hyprland, dwl, niri. If you want windows that float and overlap with titlebars and a taskbar, the way IceWM does it, there\'s almost nothing. That is Steppewm', '科技情报', '2026-08-21 23:27:38', '018eadbc811106874713162f6bdab5f324d71db31f5808fccbd542c054d29b26', '2026-08-25 16:51:40');
