INSERT INTO `news` VALUES (66, 49435675, 'Show HN: I made a Raspberry with Qwen my local car AI', 'Hacker News', 'petruspennanen', 110, 25, 'https://github.com/ThinkOffApp/CarWatch', '标题：Show HN: I made a Raspberry with Qwen my local car AI\n来源：Hacker News\n作者：petruspennanen\n评分：110\n评论数：25\n\n正文：\nFound that you can actually run a 35B Qwen model on a Pi with very impressive intelligence and stability. Built connectors for car ODB to read all about car internals, and manufacturer\'s cloud service for stuff like changing AC or opening&#x2F; locking doors. Gave it info such as the full car manual. And then hooked it up with my other agents in our discussion room! So now it can answer car questions such as \"when should I add oil and what kind of oil?\" and help you fully offline, and when online talk with the agent family that includes all the most powerful models so they know how the car is, plan new features and develop itself with them. For example, if car breaks and can\'t move the car agent informs my agent family and they can already look for a suitable train ticket without me needing to check things or do something.', '科技情报', '2026-08-25 23:20:20', '03488e097a60144d42ac9e1f8f884d3ee1fdec2269e70ab0461003938743c8f6', '2026-08-26 09:41:41');
