INSERT INTO `news` VALUES (76, 49430259, 'Show HN: I built self-hosted deployment automation tool for Windows and IIS', 'Hacker News', 'dt3ft', 24, 10, 'https://fdeploy.com/', '标题：Show HN: I built self-hosted deployment automation tool for Windows and IIS\n来源：Hacker News\n作者：dt3ft\n评分：24\n评论数：10\n\n正文：\nSeven years in the making (I admit that I did get a kid at some point which slowed down progress and brought it to a halt quite a few times), I decided to finaly release it, with a rather drastic change to the now (I believe) generous licensing model. Unlike current major players in this field, I decided to go with uncrippled, free version for commercial use for corps with up to 1M USD ARR. I poured my heart and soul into this, not because I was looking for financial success, but because I felt it just had to be done, given the price hikes wherever you look today. While my wife and kid were enjoying the beach during a vacation, I was using the time to figure out how to best tackle the problem with variable substitution and snapshots, a rather important part of the software. Pulling your hair kind of thing, many of you have likely been there, but darn does it feel good once you solve it! I know, not the best use of my time, but on the other hand, I hate the beach, so I guess this was an escape mechanism for me at that time :) I had received quite a few encouraging emails from people eager to try fDeploy back when I only had a tiny landing page out, but life has its own course and it took a while to even gather the courage to publish the first beta! As everything that sounds too good to be true in this day and age, fDeploy is no different. It does not support multi tenancy (a rather big feature which I\'d love to work down the road) and a few other things may be missing which some companies may find crucial. Either way, I see this covering the needs of a large chunk of small to medium sized companies, so some \"assembly\" may be required. If only HN had the crowd which likes to get their hands dirty and find ways to make things work ;) I\'d love to hear your thoughts and if you could take it for a spin. No signups, should be a smooth ride to get up and running and experimenting in minutes.Thanks!', '科技情报', '2026-08-25 15:32:11', '0319be648072710e361847a94b637f865919898e6d275e92ac636990e38853bd', '2026-08-26 09:41:41');
